/* amirsalmani/input — a ruled well, not a box.
 *
 * Requires tokens.css. The value is what the reader typed, so it is sans; a
 * placeholder is a hint and sits at --faint. Focus is a full-strength border
 * plus the standard outline, because there is no accent hue to glow with.
 */

.as-input {
  width: 100%;
  min-height: 44px;
  padding: .7rem .9rem;
  border: 1px solid var(--rule);
  border-radius: var(--radius-s);
  background: var(--wash);
  color: var(--fg);
  font-family: var(--sans);
  font-size: 1rem;
  line-height: 1.4;
  transition: border-color var(--fast) var(--ease-out), background var(--fast) var(--ease-out);
}
.as-input::placeholder { color: var(--faint); }
.as-input:hover { border-color: var(--glass-edge); }
.as-input:focus { outline: 2px solid var(--accent); outline-offset: 2px; border-color: var(--accent); }
.as-input[disabled] { opacity: .5; cursor: not-allowed; }
.as-input[readonly] { background: transparent; }

textarea.as-input { min-height: 7rem; resize: vertical; }
.as-input--mono { font-family: var(--mono); font-size: .95rem; letter-spacing: .01em; }

@media (prefers-contrast: more) { .as-input { background: var(--bg); border-color: var(--fg); } }
